1	export interface Scenario {
2	  customer: { yearsWithMHPCO: number };
3	  steps: Step[];
4	}
5	
6	export type Step = QuoteStep | ClaimStep;
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Item {
14	  type: string;
15	  material?: string;
16	  enchantment?: number;
17	  cursed?: boolean;
18	}
19	
20	export interface ClaimStep {
21	  op: "claim";
22	  policy: number;
23	  incident: Incident;
24	}
25	
26	export interface Incident {
27	  cause: string;
28	  damages: Damage[];
29	}
30	
31	export interface Damage {
32	  itemType: string;
33	  amount: number;
34	}
35	
36	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
37	
38	export interface ScenarioResult {
39	  results: StepResult[];
40	}
41	
42	const PROCESSING_FEE = 5;
43	
44	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
45	  sword: 100,
46	  staff: 80,
47	  amulet: 60,
48	  potion: 40,
49	  rune: 25,
50	  moonstone: 25,
51	};
52	
53	const FIRST_INSURANCE_PERCENT = 10;
54	
55	// Surcharges are applied as (amount * percent) / 100 rather than via a decimal
56	// multiplier (e.g. * 1.1): the integer intermediate is exact, whereas 100 * 1.1
57	// is 110.00000000000001 in binary floating point. Since the final amount feeds
58	// straight into Math.ceil, that error would round a 115 G premium up to 116 G.
59	const addPercent = (amount: number, percent: number): number =>
60	  amount + (amount * percent) / 100;
61	
62	const itemBasePremium = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
63	
64	const BLOCK_SIZE = 3;
65	const BLOCK_BASE_PREMIUM = 60;
66	
67	const sumItemBasePremiums = (items: Item[]): number =>
68	  items.reduce((sum, item) => sum + itemBasePremium(item), 0);
69	
70	/** Items of one and the same type, e.g. the three runes that form a block. */
71	type TypeGroup = Item[];
72	
73	const groupByType = (items: Item[]): TypeGroup[] => [
74	  ...items
75	    .reduce(
76	      (groups, item) =>
77	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
78	      new Map<string, TypeGroup>(),
79	    )
80	    .values(),
81	];
82	
83	const formsBlock = (group: TypeGroup): boolean => group.length === BLOCK_SIZE;
84	
85	const groupBasePremium = (group: TypeGroup): number =>
86	  formsBlock(group) ? BLOCK_BASE_PREMIUM : sumItemBasePremiums(group);
87	
88	const policyBasePremium = (items: Item[]): number =>
89	  groupByType(items).reduce((sum, group) => sum + groupBasePremium(group), 0);
90	
91	const CURSE_PERCENT = 50;
92	
93	/**
94	 * Item-specific modifiers apply to the affected item's own base premium,
95	 * not to the policy total.
96	 */
97	const itemSurcharges = (item: Item): number =>
98	  item.cursed ? (itemBasePremium(item) * CURSE_PERCENT) / 100 : 0;
99	
100	const sumItemSurcharges = (items: Item[]): number =>
101	  items.reduce((sum, item) => sum + itemSurcharges(item), 0);
102	
103	const quotePremium = (step: QuoteStep): number =>
104	  Math.ceil(
105	    addPercent(policyBasePremium(step.items), FIRST_INSURANCE_PERCENT) +
106	      sumItemSurcharges(step.items) +
107	      PROCESSING_FEE,
108	  );
109	
110	const runStep = (step: Step): StepResult => {
111	  if (step.op === "quote") return { premium: quotePremium(step) };
112	  throw new Error(`Unsupported step: ${step.op}`);
113	};
114	
115	export const runScenario = (scenario: Scenario): ScenarioResult => ({
116	  results: scenario.steps.map(runStep),
117	});
