/**
 * Item-scoped modifiers apply to the affected item's own base premium, not to
 * the policy total. Each entry contributes its percentage independently, so
 * several modifiers on one item add up rather than compounding.
 */
const ITEM_SURCHARGE_PERCENTS: { applies: (item: Item) => boolean; percent: number }[] = [
  { applies: (item) => item.cursed === true, percent: CURSE_PERCENT },
];

const itemSurcharge = (item: Item): number =>
  ITEM_SURCHARGE_PERCENTS.filter(({ applies }) => applies(item)).reduce(
    (surcharge, { percent }) => surcharge + percentOf(itemBasePremium(item), percent),
    0,
  );

const totalItemSurcharges = (items: Item[]): number =>
  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
